  ('hussar-apc', 'Main Body', 280, 'destruction renders the vehicle useless', 5);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note)
VALUES
  ('nazca-power-armor', 1, 'Rocket Rifle/15mm Machinegun', 'Rockets: 1D6x10 M.D. to a 3 ft (1.0 m) area (explosive) or 5D6 M.D. to a 20 ft (6.1 m) area (fragmentary); Machinegun: 2D4x10 M.D. per 10-round burst, bursts only', 1, '2000 feet (610 m) for both weapons', 'Equal to the combined number of hand to hand attacks of the pilot', 'Rockets: 6 in magazine, plus two additional clamp-on magazines; Machinegun: 300-round drum (30 bursts), plus a clamp-on spare', NULL, 'Over-and-under design; 60mm laser-guided rocket launcher over a 15mm explosive-round machinegun. Targets beyond 600 ft (183 m) need two melee rounds of aiming.'),
  ('nazca-power-armor', 2, 'Short-Range Missile Launcher', 'Varies with missile type, typically 1D6x10 or 2D4x10 M.D.', 1, '1-3 miles (1.6 to 4.8 km)', 'One at a time, or in volleys of two or four missiles', 'Eight missiles', NULL, 'Backpack launcher; primary purpose bombardment/anti-aircraft.'),
  ('nazca-power-armor', 3, 'Energy Blasters', '5D6 M.D. per blast', 1, '1000 feet (305 m)', 'Equal to the number of hand to hand attacks of the pilot', 'Effectively unlimited', NULL, 'Magical in nature; no visible weapon mounts. Backup for when other systems ammo is spent.'),
  ('nazca-power-armor', 4, 'V-Blades', '3D6 M.D. plus the suit supernatural P.S. damage (7D6 M.D. total) while the energy field is on; 3D6+4 M.D. when the suit is reduced to 200 M.D.C. or less', 1, NULL, NULL, NULL, NULL, 'Forearm slashing blades surrounded by the suit energy field.'),
  ('nazca-power-armor', 5, 'Hand to Hand Combat', 'Punch: 4D6 M.D.; Kick: 5D6 M.D.; Power Punch: 1D4x10 M.D. (counts as two attacks)', 1, NULL, NULL, NULL, NULL, 'See Power Armor Combat training, Rifts RPG page 44.'),
  ('armor-of-the-sun', 1, 'Fiery Aura', '4D6 M.D. to anything in range of the flame field; 4D6 M.D. every 5 seconds if the target remains (12D6 or 1D6x12 M.D. per full melee round)', 1, '6 feet (1.8 m)', 'Always on, instant', 'Unlimited', NULL, 'Incoming missiles take aura damage before striking the character; if destroyed by it, the armor only takes half damage. Usually only activated while flying, or it would scorch the ground.'),
  ('armor-of-the-sun', 2, 'Flame Blasts', '1D6 M.D. to 1D6x10 M.D., adjustable in 1D6 increments', 1, '2000 feet (610 m)', 'Equal to the number of hand to hand attacks of the pilot', 'Effectively unlimited', NULL, 'Fired from hands or eyes.'),
  ('armor-of-the-sun', 3, 'Blinding Aura', 'None, except vampires: -3 to save vs blindness and 2D6 damage per melee round exposed to the light', 0, 'Adjustable in 10 ft (3.0 m) increments up to a 200 ft (61 m) radius', 'Equal to the number of hand to hand attacks of the user; typically once per round', 'Unlimited', NULL, 'Targets must save vs 16 or be blinded (-8 strike/parry/dodge for 1D6 rounds); polarized helmets/goggles save vs 13 but are still -3 to all attacks for 1D4 rounds. Power armor and robot occupants unaffected.'),
  ('armor-of-the-sun', 4, 'Magical Systems', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon: environmental protection; sees the invisible and senses magic (2000 ft/610 m); sends telepathic messages to a psychic or magician up to one mile (1.6 km) away.'),
  ('armor-of-the-sun', 5, 'Hand to Hand Combat', 'Punch: 5D6 M.D.; Power Punch: 1D6x10 M.D. (counts as two attacks); Kick: 6D6 M.D.; Leap Kick: 1D6x10+6 M.D. (counts as two attacks)', 1, NULL, 'One hand to hand attack per melee (plus the pilot own)', NULL, '+2 to strike and parry, +1 to dodge, +2 to dodge when flying, +2 to dodge with punch/fall/impact; an additional melee attack at levels six and twelve', NULL),
  ('atahualpa-combat-suit', 1, 'Illapa Giant Rifle', '4D6 M.D. per shot; 3-round burst: 1D4x10 M.D.; 10-round burst: 2D4x10 M.D.', 1, '2400 feet (731.4 m)', 'Selective fire: single aimed shots, 3-round bursts, 10-round bursts; disengage mechanism prevents full-auto', '600-round magazine (60 ten-round bursts)', NULL, 'A standard Illapa rifle with larger handles and drum magazine for power armor use.'),
  ('atahualpa-combat-suit', 2, 'Mini-Missile Launchers (2)', 'Varies with missile type', 1, 'About one mile (1.6 km)', 'One at a time or in volleys of three or six missiles', '18 total; 3 in each launcher plus 6 more in an integral magazine, for 9 per launcher', NULL, 'Each launcher can be loaded with a different missile type.'),
  ('atahualpa-combat-suit', 3, 'Chest Guns', 'Standard rounds: 2D6x10 S.D.C. (counted as 1 M.D.) per 10-round burst, or 4D6x10 S.D.C. (2 M.D.) per simultaneous double burst (one melee attack); Explosive rounds: 2D6 M.D. per 10-round burst, or 4D6 M.D. per simultaneous double burst', 1, '3000 feet (915 m)', 'Each burst counts as one attack per melee; bursts only', '2000 rounds per gun (200 bursts)', NULL, 'Fire 12mm bullets vs S.D.C. targets, or explosive rounds to damage M.D.C. targets.'),
  ('atahualpa-combat-suit', 4, 'Hand to Hand Combat', NULL, 1, NULL, NULL, NULL, NULL, 'Refer to the Power Armor Combat section, Rifts RPG page 44; no separate damage figures printed.'),
  ('solar-combat-armor', 1, 'Plasma Projectors (6)', '1D4x10+10 M.D. per blast; simultaneous double hand blast: 2D4x10+20 M.D. (no initiative bonus on the double blast)', 1, '2000 feet (610 m)', 'Equal to the combined number of hand to hand attacks of the pilot', 'Effectively unlimited', '+1 to initiative when using a single projector', 'Small knobs on hands, chest, back and knees; also release the plasma used by the Flame System.'),
  ('solar-combat-armor', 2, 'Arm Mounted Rail Gun', 'A burst is 80 rounds and does 1D6x10 M.D.; bursts only', 1, '4000 feet (1220 m)', 'Equal to the number of hand to hand attacks of the pilot', '2000 rounds (25 bursts); reloading takes 5 minutes in a military hangar and requires removing the suit', NULL, 'Built into the right arm, fed from a disintegrating belt coiled in the arm and torso.'),
  ('solar-combat-armor', 3, 'Eye Lasers', '2D6 M.D. per eye, or 4D6 M.D. per simultaneous double blast', 1, '1000 feet (305 m)', 'Equal to the number of hand to hand attacks of the pilot', 'Effectively unlimited', NULL, 'Final backup weapon system.'),
  ('solar-combat-armor', 4, 'Plasma Field System/Flame System', '3D6 M.D. to anything it touches; adds 3D6+6 M.D. to hand to hand punches/kicks; ignites flammables within 10 feet (3.0 m)', 1, 'Constant field around the suit', NULL, NULL, NULL, 'Constant plasma stream held by a magnetic field.'),
  ('solar-combat-armor', 5, 'Hand to Hand Combat', 'Punch: 1D6 M.D. (4D6+6 M.D. with plasma field on); Power Punch: 3D4 M.D. (5D6+6 M.D., counts as two attacks, with plasma field on); Kick: 2D6 M.D. (5D6+6 M.D. with plasma field on); Body Block Ram: same as kick', 1, NULL, NULL, NULL, 'Use Robot and Power Armor Combat skill bonuses', NULL),
  ('slinger-light-tank', 1, 'Laser Cannon (H1-L Model)', '1D6x10+10 M.D. per blast', 1, '4000 feet (1220 m)', 'Each blast counts as one attack per melee', '500 shots per power battery (a giant E-clip weighing 100 lb./45 kg)', NULL, 'About 40 percent of tanks carry this; greater payload than the cannon but less effective against Arkhon armor.'),
  ('slinger-light-tank', 2, '90mm Cannon (H1-C Model)', 'High-Explosive: 1D4x10 M.D. to a 20 foot (6.1 m) area; Armor-Piercing Sabot-Discarding Solid: 2D4x10+10 M.D. (no blast radius)', 1, '4000 feet (1220 m)', 'Up to four shots per melee; each shot counts as one melee attack', '40 rounds total in two autoloading magazines (usually one HE, one AP)', NULL, 'About 60 percent of tanks carry this; more effective against alien vehicles and robots.'),
  ('slinger-light-tank', 3, 'Coaxial Machinegun and Grenade Launcher', 'Machinegun: 2D4x10 M.D. per 10-round burst; Grenade Launcher: 3D6 M.D. to a 10 foot (3.0 m) area, or smoke/tear gas/other grenades', 1, '2000 feet (610 m) for both', 'Bursts and single shots only; only one of the two weapons can be fired at a time', 'Machinegun: 600 rounds (60 bursts); Grenade Launcher: 60-shot magazine', NULL, 'Aimed the same way as the main gun.'),
  ('slinger-light-tank', 4, 'Bow-Mounted Machinegun', '2D4x10 M.D. per 10-round burst', 1, '2000 feet (610 m)', 'Bursts only, each counts as one melee attack', '600 rounds (60 bursts)', NULL, 'Used by the pilot to engage targets in front of the tank.'),
  ('stormwind-assault-exoskeleton', 1, 'Tri-Beam Wrist Pistol', '4D6 M.D.', 1, '1200 feet (365 m)', 'Standard', 'Effectively unlimited', NULL, 'Built-in TB-9 pistol used as a back-up weapon; double damage to most materials, except force/energy fields and Arkhon composite armor.'),
  ('stormwind-assault-exoskeleton', 2, 'Primary Weapon', 'Varies by weapon carried', 1, 'Varies by weapon carried', 'Varies by weapon carried', 'Varies by weapon carried', NULL, 'A pick of the Arkhon rifles/heavy weapons: TB-Prime Rifles (60%), FR-5 Flechette Rifles (15%), M-100 Energy Machineguns (10%), BM-2 Mortars (5%), BRL-3 Rocket Launchers (5%), or FRA-1 Auto-cannon (5%).'),
  ('stormwind-assault-exoskeleton', 3, 'Hand to Hand Combat', '2D6+7 S.D.C. punch; 4D6+7 S.D.C. kick', 0, 'Melee', NULL, NULL, NULL, 'No special combat bonuses. Wearer can carry heavy loads at 30% of the usual fatigue rate.'),
  ('ghost-wasp-aerial-power-armor', 1, 'Flechette Gun', '1D6x10 M.D. per shot; 10-round burst 2D6x10+10 M.D.; hosed burst covers 30 ft (9.1 m) radius for 3D6 M.D.', 1, '4000 feet (1220 m)', 'Standard', '400-round belt-fed back-mounted magazine', NULL, 'Rifle-shaped version of the FRA-1 auto-cannon, used against armored vehicles or massed infantry.'),
  ('ghost-wasp-aerial-power-armor', 2, 'Tri-Beam Stinger', '6D6 M.D. single shot; 3-round burst 2D4x10 M.D.', 1, '3000 feet (914 m)', 'Standard', 'Effectively unlimited', NULL, 'Medium tri-beam cannon, slightly more powerful than the M-100; main anti-armor weapon, also used in dogfights. Double damage to most materials, except force/energy fields and Arkhon composite armor.'),
  ('ghost-wasp-aerial-power-armor', 3, 'Side-Mounted Launchers (mini-missiles)', 'Varies; commonly plasma (1D6x10 M.D.)', 1, 'About one mile (1.6 km)', 'One at a time, or volleys of 2, 4, 8 or 16', '16 total, 8 per launcher', NULL, 'Two launchers between the double wings; squadrons often ripple-volley the entire payload.'),
  ('ghost-wasp-aerial-power-armor', 4, 'Long-Range Missiles', 'Varies with missile type', 1, '500 to 1200 miles (800 km to 1930 km)', 'One at a time, or volleys of two or four', 'Four total, two per launcher', NULL, 'Bomber reconfiguration; replaces the flechette rifle. Used against heavy vehicles or fixed targets.'),
  ('ghost-wasp-aerial-power-armor', 5, 'Stealth System', NULL, 0, NULL, NULL, NULL, '-50% to detect ambush/concealment (-20% if moving)', 'Holographic chameleon system; masks infrared/thermal emissions (21% chance of an unusual thermal reading). Only works under 100 mph and without firing weapons.'),
  ('ghost-wasp-aerial-power-armor', 6, 'Hand to Hand Combat', 'Restrained Punch 1D4 M.D.; Full Strength Punch 1D6 M.D.; Power Punch 3D4 M.D. (2 attacks); Kick 2D4 M.D.; Leap Kick 3D6 M.D. (2 attacks); Flying Body Block/Ram or Wing Swipe 1D6x10+10 M.D. (both wings on that side take 3D6 M.D.); Tail Strike 1D6 M.D.', 1, 'Melee', NULL, NULL, NULL, 'Pilot can engage in mega-damage hand to hand instead of using a weapon.'),
  ('death-cyclops-assault-suit', 1, 'Assault Rifle', 'Flechette: 1D4x10 M.D. per shot, 10-round burst 2D6x10+10 M.D.; Tri-Beam: 5D6 M.D. single shot, 3-round burst 1D4x10+10 M.D.', 1, 'Flechette 4000 feet (1220 m); Tri-Beam 3000 feet (914 m)', 'Standard', 'Flechette: 100-round magazine (10 bursts), two spare magazines on back clamps; Tri-Beam: unlimited', NULL, 'Two shoulder-weapon configurations: an oversized flechette gun (as FRA-1) or a tri-beam rifle version of the M-100. Typical 5-man squad runs two flechette and three tri-beam.'),
  ('death-cyclops-assault-suit', 2, 'Torso Tri-Beams (4)', '2D4+2 M.D. per beam; double beam 4D4+4 M.D.; simultaneous quadruple beam 1D4x10 M.D. (one melee attack)', 1, '500 feet (152 m)', 'Equal to the pilot''s combined hand to hand attacks', 'Effectively unlimited', NULL, 'Four light tri-beams in the torso, gesture-activated, can engage separate targets or fire simultaneously.'),
  ('death-cyclops-assault-suit', 3, 'Mini-Missile Module', 'Varies with missile type', 1, 'About one mile (1.6 km)', 'One at a time, or volleys of 2, 4, 6, 8, 10 or 12', '24 mini-missiles', NULL, 'Box launcher emptied in two volleys.'),
  ('death-cyclops-assault-suit', 4, 'Anti-Aircraft Module 1 (optional)', 'Flak Cannon: 1D4x10 M.D. to a 60 ft (18.3 m) area; Missiles: varies with type', 1, 'Flak Cannon 1 mile (1.6 km); Missiles 40-80 miles (64-128 km)', 'Flak Cannon single shots only; missiles one at a time or volleys of 2, 4 or 6', '60 flak rounds and six medium-range missiles', NULL, 'Replaces the mini-missile module; radar range increased to 100 miles/160 km, tracks up to 48 targets. Reduces max speed by 30%.'),
  ('death-cyclops-assault-suit', 5, 'Anti-Aircraft Module 2 (optional)', 'Varies with missile type', 1, 'Varies with missile type', 'One at a time, or volleys of two or three', 'Three missiles', NULL, 'Larger radar array (200 miles/320 km range, plains only) and 3 long-range missiles; limited usefulness in mountains.'),
  ('death-cyclops-assault-suit', 6, 'Mortar Module (optional)', 'Fragmentary: 3D6 M.D. to 20 ft (6.1 m) radius; Anti-Armor: 6D6 M.D. to 2 ft (0.6 m) radius', 1, 'Up to 2 miles (3.2 km); minimum 300 feet (90 m)', 'Single shot, burst of 3, or long burst of 6 (each one melee attack)', '120 bomblets', NULL, 'Dual-purpose electronically-primed rounds, similar to the BM-2 backpack mortar but with greater ammo capacity.'),
  ('death-cyclops-assault-suit', 7, 'Hand to Hand Combat', 'Restrained Punch 1D6 M.D.; Full Strength Punch or Kick 3D6 M.D.; Power Punch 1D4x10 M.D. (2 attacks); Punch with Vibro-Field activated 6D6 M.D.', 1, 'Melee', NULL, NULL, NULL, 'Pilot can engage in mega-damage hand to hand instead of using a weapon.'),
  ('great-cyclops-assault-robot', 1, 'Hand Tri-Beam Cannons (2)', '2D4x10 M.D. single blast; 4D4x10 M.D. simultaneous double blast (2 hand to hand attacks)', 1, '4000 feet (1220 m)', 'Equal to the pilot''s number of hand to hand attacks', 'Effectively unlimited', NULL, 'Built into each forearm/hand; destroyed if the hands are destroyed. Double damage to most materials, except force/energy fields and Arkhon composite armor.'),
  ('great-cyclops-assault-robot', 2, 'Torso Missile Launchers (5)', 'Varies with missile type', 1, '40 to 80 miles (64 to 128 km)', 'One at a time, or volleys of 2, 4, 8, 16 or 20', '20 missiles total, four per launcher', 'Each launcher is -2 to hit when preparing to fire, and must be called-shot', 'Concealed behind chest plates that swing outward; each launcher has 30 M.D.C.'),
  ('great-cyclops-assault-robot', 3, 'Flechette Machinegun (1, in head)', '1D4x10 M.D. per shot; 10-round burst 2D6x10+10 M.D.', 1, '4000 feet (1220 m)', 'Standard', '2000 rounds', NULL, 'Central tube beneath the chin; heavy version of the FRA-1, used against nearby targets including infantry.'),
  ('great-cyclops-assault-robot', 4, 'Tri-Beam Guns (2, lower torso)', '3D6 M.D. per beam; simultaneous double blast 6D6 M.D.', 1, '2000 feet (610 m)', 'Equal to the pilot''s combined hand to hand attacks', 'Effectively unlimited', NULL, 'Used against small vehicles, power armor and foot soldiers. Double damage to most materials, except force/energy fields and Arkhon composite armor.'),
  ('great-cyclops-assault-robot', 5, 'Mini-Missile Launchers (2, knees)', 'Varies with missile type', 1, 'About one mile (1.6 km)', 'One at a time, or volleys of 2, 4, 6, 8 or 16', '48 total: 8 missiles plus two reloads in each leg', NULL, 'Once a launcher''s 8 missiles are spent, it takes one melee round for reloads to cycle in from leg storage.'),
  ('great-cyclops-assault-robot', 6, 'Smoke Dispensers (2)', NULL, 0, NULL, NULL, NULL, '-30% to sensor rolls', 'Side-of-head compartments release a thick, heavier-than-air cloud that blinds infantry/ground vehicles and interferes with infrared/thermal and normal sight.'),
  ('great-cyclops-assault-robot', 7, 'Searchlight (1)', NULL, 0, NULL, NULL, NULL, NULL, 'Multi-optic searchlight in the head''s central ''eye''; produces normal, ultra-violet and infra-red illumination.'),
  ('great-cyclops-assault-robot', 8, 'Hand to Hand Combat', 'Restrained Punch 2D6 M.D.; Full Strength Punch 6D6 M.D.; Power Punch 2D6x10 M.D. (2 attacks); Punch with Vibro-Spikes Activated 1D6x10 M.D.', 1, 'Melee', NULL, NULL, NULL, 'Pilot can engage in mega-damage hand to hand instead of using a weapon.'),
  ('porcupine-t-10-assault-tank', 1, 'Double Cannons (2 sets)', 'Tri-Beam Cannon: 2D4x10 M.D.; Conventional Cannon varies with ammunition: High Explosive 2D6x10 M.D. to 30 ft (9.1 m) area, Plasma 2D6x10 M.D. to 20 ft (6.1 m) area, Armor Piercing Discarding Sabot 3D4x10+10 M.D. (no blast area)', 1, 'Tri-Beam 4000 feet (1220 m); Conventional 10,000 feet (3050 m)', 'Each over-and-under gun fires twice per melee (4 total); with two gunners the main guns can fire up to eight times per melee', 'Tri-beam unlimited; 30 shots per conventional cannon (60 total); gunner can dial ammo type', NULL, 'Two double cannons giving four main guns total; fire independently, no double/quadruple blasts.'),
  ('porcupine-t-10-assault-tank', 2, 'Flechette Gun Cupola', '3-round burst 1D4x10+10 M.D.; burst fire only', 1, '3000 feet (914 m)', 'Automated, +2 to strike, 5 attacks per melee', '600 rounds', '+2 to strike', 'Automated system whose main purpose is destroying incoming missiles.'),
  ('porcupine-t-10-assault-tank', 3, 'Tri-beam mini-turrets (2)', '1D4x10+10 M.D. per pulsed blast', 1, '3000 feet (914 m)', 'Equal to the gunner''s hand to hand attacks', 'Effectively unlimited', NULL, 'Operated by second and third gunners; engage flank/rear threats. Double damage to most materials, except force/energy fields and Arkhon composite armor.'),
  ('porcupine-t-10-assault-tank', 4, 'Flechette Gun Mini-Turrets (2)', '3-round burst 1D4x10+10 M.D.; burst fire only', 1, '3000 feet (914 m)', 'Automated, +2 to strike, 5 attacks per melee', '600 rounds', '+2 to strike', 'Front-mounted, operated by the same gunners as the side tri-beam turrets (cannot use both weapons at once); tank commander/pilot can also take control.'),
  ('porcupine-t-10-assault-tank', 5, 'Mini-Missile Turret', 'Varies with missile type', 1, 'About one mile (1.6 km)', 'One at a time, or volleys of 2, 4, 8 or 10', 'Twenty mini-missiles', NULL, 'Box-shaped launcher in back.'),
  ('evil-eye-apc', 1, '"Evil Eye" Particle Beam Irradiator', '4D6 M.D. to a 30 ft (9.1 m) radius in front of the vehicle; armored humans/S.D.C. humanoids also take 3D6 S.D.C. from residual heat', 1, '200 feet (61 m)', 'Each pulse counts as two melee attacks/actions (trigger held 4-6 seconds); usable up to three times per melee', 'Effectively unlimited', NULL, 'Wide-beam front weapon; a burst of short-lived intense radiation that destroys matter and bakes even armored soldiers with residual heat. Power armor, robots and larger vehicles get a save vs lethal poison (14 or higher) to avoid the heat effect.'),
  ('evil-eye-apc', 2, 'Pintle-mounted Tri-Beam', '1D4x10+10 M.D. per pulse blast', 1, '3000 feet (914 m)', 'Equal to the gunner''s hand to hand attacks', 'Effectively unlimited', NULL, 'Gunner must leave the vehicle''s safety and is exposed to enemy fire; hitting the gunner requires a called shot at -2 due to the gun shield. Double damage to most materials, except force/energy fields and Arkhon composite armor.'),
  ('evil-eye-apc', 3, 'Mini-Missile Launchers (2)', 'Varies by missile type', 1, 'About one mile (1.6 km)', 'One at a time, or volleys of 2, 4, 8 or 16', '16 total, eight per launcher', NULL, 'One launcher per side; provides the APC''s main long-distance striking power.'),
  ('spikefish-attack-fighter', 1, 'Double Tri-Beam Cannons (2)', '2D4x10 M.D. per double blast', 1, '4000 feet (1220 m)', 'Equal to the pilot''s combined hand to hand attacks', 'Effectively unlimited', NULL, 'Side-mounted; main dogfight/strafing weapons; the two double guns cannot align to fire at the same target simultaneously. Double damage to most materials except force fields and Cerasteel armor.'),
  ('spikefish-attack-fighter', 2, 'Missile Pylons', 'Varies with missile type', 1, 'Varies with missile type', 'One at a time, or volleys of 2, 4, or 8', 'Up to eight medium-range missiles, four long-range missiles, or a combination', NULL, 'Underside-mounted.'),
  ('counterstrike-power-armor', 1, 'I-Beam Gatling Gun', '2D6x10 M.D. per burst of 20 rounds (bursts only)', 1, '3000 feet (914 m)', 'Equal to pilot''s hand to hand attacks', '2000 rounds in storage compartment', NULL, 'Mounted on right forearm; anti-armor primary purpose'),
  ('counterstrike-power-armor', 2, 'Plasma Blaster', '1D6x10 M.D. per blast', 1, '2000 feet (610 m)', 'Equal to pilot''s hand to hand attacks', 'Effectively unlimited', NULL, 'Mounted on other forearm; anti-armor'),
  ('counterstrike-power-armor', 3, 'Mini-Missile Launchers (2)', 'Varies with missile type', 1, 'About 1 mile (1.6 km)', 'One at a time, or volleys of 2, 4, 6, 8 or 16', '16 total; 8 per launcher', NULL, 'Beneath the wings, anti-aircraft'),
  ('counterstrike-power-armor', 4, 'Torso Lasers (2)', '2D6 M.D. per laser, or 4D6 M.D. simultaneous double blast', 1, '2000 feet (610 m)', 'Equal to pilot''s hand to hand attacks', 'Effectively unlimited', NULL, 'Anti-personnel'),
  ('counterstrike-power-armor', 5, 'Grenade Launchers (2)', '3D6 M.D. per grenade to 30 ft (9.1 m); burst of 3 does 3D6+6 M.D. to 60 ft (18.3 m); long burst of 10 (counts as two attacks) does 4D6+6 M.D. to 100 ft (30.5 m)', 1, '4000 feet (1220 m)', 'Single shots, or bursts of 3 or 10 grenades', '60 total; 30 per launcher', NULL, 'Back-mounted magazine, can air-burst against aircraft/missiles'),
  ('counterstrike-power-armor', 6, 'Double Wrist Blades', '4D6 M.D. per slash', 1, 'Hand to hand', 'Equal to pilot''s hand to hand attacks', NULL, NULL, 'Energized wrist-mounted blades'),
  ('counterstrike-power-armor', 7, 'Hand to Hand Combat', 'Restrained Punch: 1 M.D.; Full Strength Punch or Kick: 1D6 M.D.; Power Punch or Leap Kick: 3D6 M.D. (counts as two attacks)', 1, 'Hand to hand', NULL, NULL, '+1 attack per melee at levels 1, 6, 12 (plus pilot''s); +1 to dodge at levels 1, 4, 8; +2 to roll with punch/fall/impact; +2 to pull punch; critical strike same as pilot''s', NULL),
  ('neo-abrams-m10a1-main-battle-tank', 1, '120mm I-Beam Cannon', 'AP Round: 5D6x10 M.D.; High Explosive: 3D6x10 M.D. to 50 ft (15.2 m) radius; Canister: 1D4x10 M.D. to all targets in a 60 ft (18.3 m) cone', 1, '11,000 feet (about 2 miles/3.2 km) for AP/HE; 1000 feet (305 m) for canister', 'Up to 3 times per melee (or pilot''s hand to hand attacks, whichever is less)', '60-round magazine, typically 20 rounds of each ammo type', NULL, 'Anti-armor primary'),
  ('neo-abrams-m10a1-main-battle-tank', 2, 'Coaxial Grenade Launcher', '3D6 M.D. per grenade to 30 ft (9.1 m); burst of 3 does 3D6+6 M.D. to 60 ft (18.3 m); long burst of 10 (counts as two attacks) does 4D6+6 M.D. to 100 ft (30.5 m)', 1, '4000 feet (1220 m)', 'Single shots, or bursts of 3 or 10 grenades', '120 total', NULL, 'Can laser-designate a target; grenades can be air-burst vs aircraft/missiles'),
  ('neo-abrams-m10a1-main-battle-tank', 3, 'Plasma Machinegun (Cupola)', '1D6x10 M.D. per burst (bursts only)', 1, '2000 feet (610 m)', 'Equal to gunner''s hand to hand attacks', 'Effectively unlimited', NULL, 'Ignites flammables within 20 ft (6.1 m)'),
  ('neo-abrams-m10a1-main-battle-tank', 4, 'Mini-Missile Launchers (2)', 'Varies with missile type', 1, 'About 1 mile (1.6 km)', 'One at a time, or volleys of 2, 4, 8 or 16', '16 total, 8 per launcher', NULL, 'Anti-aircraft'),
  ('neo-abrams-m10a1-main-battle-tank', 5, 'Bow-Mounted Plasma Machinegun', '1D6x10 M.D. per burst (bursts only)', 1, '2000 feet (610 m)', 'Equal to gunner''s hand to hand attacks', 'Effectively unlimited', NULL, 'Used by secondary gunner or pilot'),
