SELECT 'all 23 South America 2 vehicles are in' AS assertion, count(*) AS got, 23 AS want
  FROM vehicles WHERE slug IN ('nazca-power-armor', 'armor-of-the-sun', 'atahualpa-combat-suit', 'solar-combat-armor', 'slinger-light-tank', 'stormwind-assault-exoskeleton', 'ghost-wasp-aerial-power-armor', 'death-cyclops-assault-suit', 'great-cyclops-assault-robot', 'porcupine-t-10-assault-tank', 'evil-eye-apc', 'spikefish-attack-fighter', 'counterstrike-power-armor', 'neo-abrams-m10a1-main-battle-tank', 'neo-bradley-m6-ifv-scout-vehicle', 'neo-apache-ah-50-attack-aerodyne', 'mecha-lizard-power-armor', 'toro-minotaur-power-armor', 'glitter-boy-number-7', 'mastodon-battle-robot', 'galapagos-submersible-robot', 'puma-class-medium-battle-tank', 'hussar-apc');
SELECT 'and every one cites South America 2 by page' AS assertion, count(*) AS got, 23 AS want
  FROM vehicles WHERE source_book LIKE 'Rifts World Book 9: South America 2 p.%';
SELECT 'their 158 M.D.C. locations are in' AS assertion, count(*) AS got, 158 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('nazca-power-armor', 'armor-of-the-sun', 'atahualpa-combat-suit', 'solar-combat-armor', 'slinger-light-tank', 'stormwind-assault-exoskeleton', 'ghost-wasp-aerial-power-armor', 'death-cyclops-assault-suit', 'great-cyclops-assault-robot', 'porcupine-t-10-assault-tank', 'evil-eye-apc', 'spikefish-attack-fighter', 'counterstrike-power-armor', 'neo-abrams-m10a1-main-battle-tank', 'neo-bradley-m6-ifv-scout-vehicle', 'neo-apache-ah-50-attack-aerodyne', 'mecha-lizard-power-armor', 'toro-minotaur-power-armor', 'glitter-boy-number-7', 'mastodon-battle-robot', 'galapagos-submersible-robot', 'puma-class-medium-battle-tank', 'hussar-apc');
SELECT 'their 122 weapon entries are in' AS assertion, count(*) AS got, 122 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('nazca-power-armor', 'armor-of-the-sun', 'atahualpa-combat-suit', 'solar-combat-armor', 'slinger-light-tank', 'stormwind-assault-exoskeleton', 'ghost-wasp-aerial-power-armor', 'death-cyclops-assault-suit', 'great-cyclops-assault-robot', 'porcupine-t-10-assault-tank', 'evil-eye-apc', 'spikefish-attack-fighter', 'counterstrike-power-armor', 'neo-abrams-m10a1-main-battle-tank', 'neo-bradley-m6-ifv-scout-vehicle', 'neo-apache-ah-50-attack-aerodyne', 'mecha-lizard-power-armor', 'toro-minotaur-power-armor', 'glitter-boy-number-7', 'mastodon-battle-robot', 'galapagos-submersible-robot', 'puma-class-medium-battle-tank', 'hussar-apc');

